{
  "name": "@starkita7/agent-pulse",
  "version": "0.1.4",
  "description": "Windows system tray status indicator for opencode — real-time AI status with desktop notifications",
  "main": "dist/index.js",
  "types": "dist/index.d.ts",
  "files": [
    "dist/",
    "tray/",
    "assets/"
  ],
  "scripts": {
    "build": "tsc",
    "dev": "tsc --watch",
    "prepublishOnly": "npm run build"
  },
  "keywords": ["opencode", "opencode-plugin", "tray", "notification", "status", "windows"],
  "repository": {
    "type": "git",
    "url": "https://github.com/anomalyco/agent-pulse"
  },
  "license": "MIT",
  "dependencies": {
    "@opencode-ai/plugin": "^1.16.0",
    "node-notifier": "^10.0.1",
    "play-sound": "^1.1.6",
    "systray": "^1.0.5"
  },
  "devDependencies": {
    "typescript": "^5.0.0",
    "@types/node": "^20.0.0",
    "@types/node-notifier": "^8.0.0"
  },
  "peerDependencies": {
    "@opencode-ai/sdk": "*"
  }
}
